UNIT='الدوال الأصلية والحساب التكاملي'
FIELD='تحليل'
LEVEL='3 ع ت'
TOOLS=r'المنهاج ، الكتاب المدرسي (الجزء الأول) ، الآلة الحاسبة البيانية ، برمجية Geogebra.'
S=[]
I=lambda a,b,f:r'\displaystyle\int_{%s}^{%s}%s\,\mathrm dx'%(a,b,f)
# ---------------------------------------------------------------- 36
S.append(sess('36',r'الدوال الأصلية: تعريف وخواص',
[r'المشتقات ، المعادلات التفاضلية $y^{\prime}=f$.'],
[r'تعريف دالة أصلية لدالة على مجال ، والتحقق منها.'],TOOLS,
r'ما الدالة التي مشتقتها $2x$ ؟ هل هي وحيدة؟',
ACT('01')+Q(r'احسب مشتقات الدوال: $x^2$ ، $x^2+1$ ، $x^2-7$.',r'ماذا تلاحظ؟ وما الفرق بين اثنتين منها؟')
+DIS()+Q(r'$(x^2)^{\prime}=(x^2+1)^{\prime}=(x^2-7)^{\prime}=\RR{2x}$.',r'كلها مشتقتها $2x$ ، والفرق بين اثنتين منها \RR{عدد ثابت}: نسميها \textbf{دوال أصلية} للدالة $x\mapsto2x$.'),
DEF()+r'\ $f$ دالة معرفة على مجال $I$. نسمي \textbf{دالة أصلية} لـ $f$ على $I$ كل دالة $F$ قابلة للاشتقاق على $I$ وتحقق: $\RR{F^{\prime}(x)=f(x)}$ من أجل كل $x$ من $I$.'
+PRO()+Q(r'كل دالة \textbf{مستمرة} على مجال تقبل دوالًا أصلية عليه.',r'إذا كانت $F$ دالة أصلية لـ $f$ على $I$ فإن كل الدوال الأصلية لـ $f$ هي $\RR{x\mapsto F(x)+c}$ ($c$ ثابت).',r'دالة أصلية لـ $f+g$ هي $F+G$ ، ولـ $kf$ هي $kF$.')
+PRF()+r'\ للخاصية (2): إذا كانت $F$ و $G$ أصليتين لـ $f$ فإن $(G-F)^{\prime}=f-f=0$ ، إذن $G-F$ ثابتة على المجال $I$.'
+EX('أمثلة محلولة')+Q(r'$F(x)=x^3-x$ أصلية لـ $f(x)=3x^2-1$ لأن $F^{\prime}(x)=\RR{3x^2-1}$.',r'$F(x)=xe^x$ أصلية لـ $f(x)=(x+1)e^x$ لأن $F^{\prime}(x)=e^x+xe^x=\RR{(x+1)e^x}$.',r'$F(x)=x\ln x-x$ أصلية لـ $\ln x$ على $]0;+\infty[$ لأن $F^{\prime}(x)=\ln x+x\times\dfrac1x-1=\RR{\ln x}$.')
+WARN()+r'\ نتحقق دائمًا بالاشتقاق: $F^{\prime}=f$.',
TT()+r'\par'+Q(r'بيّن أن $F(x)=(x-1)e^x$ دالة أصلية لـ $f(x)=xe^x$ على $\mathbb R$.',r'عيّن العددين $a$ و $b$ حتى تكون $F(x)=(ax+b)e^{-x}$ دالة أصلية لـ $f(x)=(2x-1)e^{-x}$.')
+SOL()+Q(r'$F^{\prime}(x)=e^x+(x-1)e^x=\RR{xe^x}=f(x)$.',r'$F^{\prime}(x)=ae^{-x}-(ax+b)e^{-x}=(-ax+a-b)e^{-x}$.\par بالمطابقة مع $(2x-1)e^{-x}$: $-a=2$ و $a-b=-1$ ، إذن $\RR{a=-2}$ و $\RR{b=-1}$: $F(x)=(-2x-1)e^{-x}$.')
+HW(r'تمارين من باب الدوال الأصلية.'),
[r'سؤال عكسي.',r'مناقشة النشاط.',r'التحقق بالاشتقاق.',r'تقويم فردي.']))
# ---------------------------------------------------------------- 37
TAB37=r'''\par\smallskip\begin{LTR}\centering {\renewcommand{\arraystretch}{1.9}\begin{tabular}{|C|C|C|}\hline
\rowcolor{cSec!12}\ar{المجال} & $F(x)$ \ar{(دالة أصلية)} & $f(x)$\\\hline
$\mathbb R$ & $ax$ & $a$\\\hline
$\mathbb R$ & $\dfrac{x^{n+1}}{n+1}$ & $x^n\ (n\in\mathbb N)$\\\hline
$]0;+\infty[$ \ar{أو} $]-\infty;0[$ & $-\dfrac1x$ & $\dfrac1{x^2}$\\\hline
$]0;+\infty[$ & $2\sqrt x$ & $\dfrac1{\sqrt x}$\\\hline
$]0;+\infty[$ & $\ln x$ & $\dfrac1x$\\\hline
$\mathbb R$ & $e^x$ & $e^x$\\\hline
$\mathbb R$ & $\sin x$ & $\cos x$\\\hline
$\mathbb R$ & $-\cos x$ & $\sin x$\\\hline
\end{tabular}}\end{LTR}\par '''
S.append(sess('37',r'الدوال الأصلية للدوال المألوفة ، الدالة الأصلية التي تحقق شرطًا',
[r'تعريف الدالة الأصلية ، جدول المشتقات.'],
[r'تعيين الدوال الأصلية للدوال المألوفة.',r'تعيين الدالة الأصلية التي تأخذ القيمة $y_0$ عند $x_0$.'],TOOLS,
r'اقرأ جدول المشتقات «بالعكس».',
ACT('02')+Q(r'من $(x^3)^{\prime}=3x^2$ استنتج دالة أصلية لـ $x^2$.',r'من $(\ln x)^{\prime}=\dfrac1x$ و $(\sin x)^{\prime}=\cos x$ استنتج دالتين أصليتين.',r'$f(x)=3x^2+2x-1$: عيّن الدالة الأصلية $F$ التي تحقق $F(1)=0$.')
+DIS()+Q(r'$\left(\dfrac{x^3}3\right)^{\prime}=x^2$: دالة أصلية لـ $x^2$ هي $\RR{\dfrac{x^3}3}$.',r'دالة أصلية لـ $\dfrac1x$ على $]0;+\infty[$ هي $\RR{\ln x}$ ، ولـ $\cos x$ هي $\RR{\sin x}$.',r'$F(x)=x^3+x^2-x+c$ ؛ $F(1)=1+1-1+c=0$ ، $c=-1$: $\RR{F(x)=x^3+x^2-x-1}$.'),
L('cThm','جدول الدوال الأصلية للدوال المألوفة')+TAB37
+PRO('الشرط الابتدائي')+r'\ من أجل $x_0$ من $I$ و $y_0$ حقيقي ، توجد \textbf{دالة أصلية وحيدة} $F$ لـ $f$ على $I$ تحقق $\RR{F(x_0)=y_0}$.'
+EX('أمثلة محلولة')+Q(r'$g(x)=\cos x+e^x$ ، الأصلية التي تنعدم عند $0$: $G(x)=\sin x+e^x+c$ ، $G(0)=1+c=0$: $\RR{G(x)=\sin x+e^x-1}$.',r'$h(x)=\dfrac1x+2x$ على $]0;+\infty[$ مع $H(1)=3$: $H(x)=\ln x+x^2+c$ ، $1+c=3$: $\RR{H(x)=\ln x+x^2+2}$.')
+WARN()+r'\ $\dfrac1x$ أصليتها $\ln x$ على $]0;+\infty[$ فقط.',
TT()+r'\par $f(x)=x^3-\dfrac4{x^2}+\dfrac1{\sqrt x}$ على $]0;+\infty[$.'+Q(r'عيّن الدوال الأصلية لـ $f$.',r'عيّن الدالة الأصلية $F$ التي تحقق $F(1)=0$.')
+SOL()+Q(r'$F(x)=\dfrac{x^4}4-4\times\left(-\dfrac1x\right)+2\sqrt x+c=\RR{\dfrac{x^4}4+\dfrac4x+2\sqrt x+c}$.',r'$F(1)=\dfrac14+4+2+c=\dfrac{25}4+c=0$ ، $c=-\dfrac{25}4$: $\RR{F(x)=\dfrac{x^4}4+\dfrac4x+2\sqrt x-\dfrac{25}4}$.')
+HW(r'تمارين 4 إلى 6 صفحة 158 ، و 24 ، 25 ، 27 ، 28 صفحة 160.'),
[r'قراءة عكسية.',r'مناقشة النشاط.',r'جدول يُحفظ.',r'تقويم فردي.']))
# ---------------------------------------------------------------- 38
TAB38=r'''\par\smallskip\begin{LTR}\centering {\renewcommand{\arraystretch}{1.9}\begin{tabular}{|C|C|C|}\hline
\rowcolor{cSec!12}\ar{الشرط} & \ar{دالة أصلية} & \ar{الدالة}\\\hline
-- & $\dfrac{u^{n+1}}{n+1}$ & $u^{\prime}u^n\ (n\in\mathbb N)$\\\hline
$u\neq0$ & $-\dfrac1u$ & $\dfrac{u^{\prime}}{u^2}$\\\hline
$u>0$ & $2\sqrt u$ & $\dfrac{u^{\prime}}{\sqrt u}$\\\hline
$u>0$ & $\ln u$ & $\dfrac{u^{\prime}}u$\\\hline
-- & $e^u$ & $u^{\prime}e^u$\\\hline
$a\neq0$ & $\dfrac1a\sin(ax+b)$ & $\cos(ax+b)$\\\hline
$a\neq0$ & $-\dfrac1a\cos(ax+b)$ & $\sin(ax+b)$\\\hline
\end{tabular}}\end{LTR}\par '''
S.append(sess('38',r'قواعد حساب الدوال الأصلية',
[r'الدوال الأصلية للدوال المألوفة ، مشتقة دالة مركبة.'],
[r'تعيين دوال أصلية لدوال من الأشكال $u^{\prime}u^n$ ، $\frac{u^{\prime}}u$ ، $u^{\prime}e^u$ ، $\ldots$'],TOOLS,
r'ما مشتقة $(x^2+1)^4$ ؟',
ACT('03')+Q(r'احسب مشتقة $(x^2+1)^4$.',r'استنتج دالة أصلية لـ $2x(x^2+1)^3$.',r'احسب مشتقة $\ln(x^2+1)$ واستنتج دالة أصلية لـ $\dfrac x{x^2+1}$.')
+DIS()+Q(r'$\big((x^2+1)^4\big)^{\prime}=4\times2x(x^2+1)^3=\RR{8x(x^2+1)^3}$.',r'$2x(x^2+1)^3=\dfrac14\times8x(x^2+1)^3$ ، إذن دالة أصلية: $\RR{\dfrac14(x^2+1)^4}$.',r'$\big(\ln(x^2+1)\big)^{\prime}=\dfrac{2x}{x^2+1}$ ، إذن $\dfrac x{x^2+1}=\dfrac12\times\dfrac{2x}{x^2+1}$ أصليتها $\RR{\dfrac12\ln(x^2+1)}$.'),
L('cThm','جدول القواعد ($u$ قابلة للاشتقاق على $I$)')+TAB38
+MET('التعرف على الشكل')+Q(r'نختار $u(x)$ ونحسب $u^{\prime}(x)$.',r'نُظهر $u^{\prime}$ بالضرب والقسمة على \textbf{ثابت} فقط.',r'نطبق القاعدة ثم نتحقق بالاشتقاق.')
+EX('أمثلة محلولة')+Q(r'$h(x)=e^{2x}$: $u=2x$ ، $h=\frac12\times2e^{2x}$: $\RR{H(x)=\dfrac12e^{2x}}$.',r'$k(x)=\dfrac{\ln x}x$ على $]0;+\infty[$: $u=\ln x$ ، $u^{\prime}=\frac1x$ ، $k=u^{\prime}u$: $\RR{K(x)=\dfrac12(\ln x)^2}$.',r'$m(x)=\dfrac{e^x}{e^x+1}$: $u=e^x+1>0$ ، $m=\dfrac{u^{\prime}}u$: $\RR{M(x)=\ln\left(e^x+1\right)}$.',r'$p(x)=\dfrac3{(3x+1)^2}$ على $\left]-\frac13;+\infty\right[$: $\RR{P(x)=-\dfrac1{3x+1}}$.')
+WARN()+r'\ لا نستطيع إظهار $u^{\prime}$ بالضرب في متغير ($x$): نُغير الطريقة.',
TT()+r'\par عيّن دالة أصلية لكل دالة:'+Q(r'$f(x)=\dfrac{2x+1}{x^2+x+1}$ على $\mathbb R$.',r'$g(x)=xe^{x^2}$.',r'$h(x)=\cos x\sin^2x$.',r'$k(x)=\dfrac{2x}{\sqrt{x^2+5}}$.')
+SOL()+Q(r'$u=x^2+x+1>0$ ($\Delta<0$) و $u^{\prime}=2x+1$: $\RR{F(x)=\ln\left(x^2+x+1\right)}$.',r'$u=x^2$ ، $g=\frac12\times2xe^{x^2}$: $\RR{G(x)=\dfrac12e^{x^2}}$.',r'$u=\sin x$ ، $u^{\prime}=\cos x$ ، $h=u^{\prime}u^2$: $\RR{H(x)=\dfrac{\sin^3x}3}$.',r'$u=x^2+5$ ، $k=\dfrac{u^{\prime}}{\sqrt u}$: $\RR{K(x)=2\sqrt{x^2+5}}$.')
+HW(r'تمارين 53 ، 54 ، 56 ، 57 صفحة 162.'),
[r'سؤال تمهيدي.',r'مناقشة النشاط.',r'جدول القواعد.',r'تقويم فردي.']))
# ---------------------------------------------------------------- 39
S.append(sess('39',r'المعادلات التفاضلية $y^{\prime}=f$ ، $y^{\prime\prime}=f$ ، $y^{\prime\prime}+\omega^2y=0$',
[r'الدوال الأصلية ، الدوال المثلثية.'],
[r'حل معادلات تفاضلية بسيطة مع شروط ابتدائية.'],TOOLS,
r'نابض مهتز: تسارعه متناسب مع موضعه وعكس إشارته. كيف نكتب ذلك؟',
ACT('04')+Q(r'حل المعادلة $y^{\prime\prime}=6x$.',r'تحقق أن $\cos2x$ و $\sin2x$ حلان للمعادلة $y^{\prime\prime}=-4y$.')
+DIS()+Q(r'$y^{\prime}=3x^2+a$ ، ثم $\RR{y=x^3+ax+b}$ ($a$ و $b$ ثابتان).',r'$(\cos2x)^{\prime\prime}=-4\cos2x$ و $(\sin2x)^{\prime\prime}=-4\sin2x$: \RR{حلان}.'),
PRO()+Q(r'حلول $y^{\prime}=f$: الدوال الأصلية لـ $f$.',r'حلول $y^{\prime\prime}=f$: نأخذ دالة أصلية مرتين (ثابتان).',r'حلول $y^{\prime\prime}+\omega^2y=0$: $\RR{y=A\cos\omega x+B\sin\omega x}$ ($A$ و $B$ ثابتان).')
+EX('أمثلة محلولة')+Q(r'$y^{\prime\prime}=6x$ مع $y(0)=1$ و $y^{\prime}(0)=0$: $y^{\prime}=3x^2+a$ ، $a=0$ ؛ $y=x^3+b$ ، $b=1$: $\RR{y=x^3+1}$.',r'$y^{\prime\prime}+4y=0$ مع $y(0)=1$ و $y^{\prime}(0)=2$: $y=A\cos2x+B\sin2x$ ، $A=1$ ، $y^{\prime}(0)=2B=2$: $\RR{y=\cos2x+\sin2x}$.')
+WARN()+r'\ معادلة من الرتبة الثانية تحتاج \textbf{شرطين} لتعيين حل وحيد.',
TT()+r'\par'+Q(r'حل $y^{\prime\prime}+9y=0$ مع $y(0)=0$ و $y^{\prime}(0)=3$.',r'حل $y^{\prime}=e^{2x}+1$ مع $y(0)=0$.')
+SOL()+Q(r'$y=A\cos3x+B\sin3x$ ؛ $y(0)=A=0$ ؛ $y^{\prime}(0)=3B=3$ ، $B=1$: $\RR{y=\sin3x}$.',r'$y=\dfrac12e^{2x}+x+c$ ؛ $y(0)=\dfrac12+c=0$: $\RR{y=\dfrac12e^{2x}+x-\dfrac12}$.')
+HW(r'تمارين 31 إلى 34 صفحة 161.'),
[r'وضعية فيزيائية.',r'التحقق بالتعويض.',r'جدول الحالات.',r'تقويم فردي.']))
# ---------------------------------------------------------------- 40
G40=GR(r'''\fill[cDef!25] (0,0) -- plot[domain=0:2,samples=50] (\x,{\x*\x}) -- (2,0) -- cycle;
\draw[cDef,very thick,domain=-1:2.2,samples=60] plot (\x,{\x*\x}) node[right]{$(C_f):y=x^2$};
\draw[densely dotted] (2,0)--(2,4); \node[cThm] at (1.45,1){$\mathcal A$};''',(-1.3,3),(-0.6,5),x=1.1,y=0.6)
S.append(sess('40',r'الحساب التكاملي: المقاربة والتعريف',
[r'الدوال الأصلية ، مساحات الأشكال البسيطة.'],
[r'حساب تكامل دالة على مجال وتفسيره بمساحة.'],TOOLS,
r'كيف نحسب مساحة حيز محدود بمنحنٍ؟',
ACT('05')+r'\ (النشاطان 01 صفحة 166 و 02 صفحة 167) $f(x)=2x+1$ على $[1;3]$.'+Q(r'احسب مساحة الحيز تحت المستقيم بين $x=1$ و $x=3$ (شبه منحرف).',r'$F(x)=x^2+x$: تحقق أنها أصلية لـ $f$ واحسب $F(3)-F(1)$.')
+DIS()+Q(r'القاعدتان $f(1)=3$ و $f(3)=7$ والارتفاع $2$: $\mathcal A=\dfrac{(3+7)\times2}2=\RR{10}$.',r'$F^{\prime}(x)=2x+1$ ؛ $F(3)-F(1)=12-2=\RR{10}$: \RR{نفس النتيجة}.'),
DEF()+r'\ $f$ مستمرة على مجال $I$ ، $a$ و $b$ من $I$ و $F$ دالة أصلية لها: $\RR{'+I('a','b','f(x)')+r'=F(b)-F(a)=\big[F(x)\big]_a^b}$.'
+PRO('التفسير الهندسي')+r'\ إذا كانت $f\geqslant0$ على $[a;b]$ فإن $'+I('a','b','f(x)')+r'$ هو مساحة الحيز المحدد بـ $(C_f)$ ومحور الفواصل والمستقيمين $x=a$ و $x=b$ (بوحدة المساحات $\mathrm{u.a}$).'
+EX('مثال مع الرسم والوضع النسبي')+r'\ $'+I('0','2','x^2')+r'$: ندرس الوضع النسبي لـ $(C_f)$ ومحور الفواصل:'
+VP(['0','2'],'x^2',{0:('O(0;0)','يمس')},['فوق'],'(C_f)',"(xx')")+G40
+r'$'+I('0','2','x^2')+r'=\left[\dfrac{x^3}3\right]_0^2=\dfrac83-0=\RR{\dfrac83\ \mathrm{u.a}}$.'
+WARN()+r'\ وحدة المساحات $\mathrm{u.a}$ تتعلق بوحدتي المعلم.',
TT()+r'\par احسب:'+Q(r'$'+I('1','e',r'\dfrac1x')+r'$.',r'$'+I(r'0',r'\frac\pi2',r'\cos x')+r'$.',r'$'+I('0','1','e^{2x}')+r'$.')
+SOL()+Q(r'$\big[\ln x\big]_1^e=1-0=\RR{1}$.',r'$\big[\sin x\big]_0^{\frac\pi2}=1-0=\RR{1}$.',r'$\left[\dfrac12e^{2x}\right]_0^1=\RR{\dfrac{e^2-1}2}$.')
+HW(r'تمرين 10 صفحة 184 ، وتمارين 11 إلى 14 صفحتي 183 و 184.'),
[r'سؤال تاريخي.',r'نشاطا الكتاب.',r'رسم الحيز الملوّن.',r'تقويم فردي.']))
# ---------------------------------------------------------------- 41
G41=GR(r'''\fill[cThm!25] plot[domain=0:1,samples=40] (\x,\x) -- plot[domain=1:0,samples=40] (\x,{\x*\x}) -- cycle;
\draw[cDef,very thick] (-0.3,-0.3)--(1.4,1.4) node[above left]{$(C_f):y=x$};
\draw[cRem!80!black,very thick,domain=-0.5:1.25,samples=40] plot (\x,{\x*\x}); \node[cRem!80!black] at (1.45,0.75){$(C_g):y=x^2$};
\node[cThm] at (0.62,0.5){$\mathcal A$};''',(-0.6,1.8),(-0.4,1.6),x=2.6,y=2.6,xt=[1],yt=[1])
