S.append(sess('41',r'خواص التكامل ، مساحة حيز بين منحنيين',
[r'تعريف التكامل.'],
[r'استعمال خواص التكامل.',r'حساب مساحة حيز بين منحنيين.'],TOOLS,
r'كيف نحسب المساحة بين منحنيي $y=x$ و $y=x^2$ ؟',
ACT('06')+r'\ $f(x)=x$ و $g(x)=x^2$ على $[0;1]$.'+Q(r'ادرس إشارة $f(x)-g(x)$ على $[0;1]$.',r'احسب $'+I('0','1','x')+r'$ و $'+I('0','1','x^2')+r'$ ، ثم الفرق.')
+DIS()+Q(r'$f(x)-g(x)=x(1-x)\geqslant0$ على $[0;1]$: $(C_f)$ \RR{فوق} $(C_g)$.',r'$\dfrac12-\dfrac13=\RR{\dfrac16}$: هو مساحة الحيز بين المنحنيين.'),
PRO('خواص التكامل')+Q(r'\textbf{الخطية}: $\RR{\int_a^b(\alpha f+\beta g)=\alpha\int_a^bf+\beta\int_a^bg}$.',r'\textbf{علاقة شال}: $\RR{\int_a^cf=\int_a^bf+\int_b^cf}$ ؛ $\int_a^af=0$ ؛ $\int_b^af=-\int_a^bf$.',r'\textbf{الترتيب} ($a\leqslant b$): إذا كان $f\geqslant0$ فإن $\int_a^bf\geqslant0$ ؛ إذا كان $f\leqslant g$ فإن $\int_a^bf\leqslant\int_a^bg$.')
+PRO('مساحة حيز بين منحنيين')+r'\ إذا كان $(C_f)$ فوق $(C_g)$ على $[a;b]$: $\RR{\mathcal A='+I('a','b',r'\big(f(x)-g(x)\big)')+r'}$.'
+EX('مثال: الوضع النسبي أولًا ثم الرسم')+VP(['0','1'],'x-x^2',{0:'O(0;0)',1:'A(1;1)'},['فوق'],'(C_f)','(C_g)')+G41
+r'$\mathcal A='+I('0','1','(x-x^2)')+r'=\left[\dfrac{x^2}2-\dfrac{x^3}3\right]_0^1=\RR{\dfrac16\ \mathrm{u.a}}$.'
+WARN()+r'\ ندرس إشارة الفرق قبل الحساب ، ونطرح الأسفل من الأعلى.',
TT()+r'\par'+Q(r'احسب بالخطية $I='+I('0','1','(2x+3e^x)')+r'$.',r'احسب مساحة الحيز المحصور بين $y=x^2$ و $y=2x$.')
+SOL()+Q(r'$I=2\times\dfrac12+3(e-1)=\RR{3e-2}$.',r'التقاطع: $x^2=2x\iff x=0$ أو $x=2$ ؛ $2x-x^2=x(2-x)\geqslant0$ على $[0;2]$:'
   +VP(['0','2'],'2x-x^2',{0:'O(0;0)',1:'A(2;4)'},['فوق'],'(y=2x)','(y=x^2)')+G41b
   +r'$\mathcal A='+I('0','2','(2x-x^2)')+r'=\left[x^2-\dfrac{x^3}3\right]_0^2=4-\dfrac83=\RR{\dfrac43\ \mathrm{u.a}}$.')
+HW(r'تمارين 30 إلى 33 صفحة 186.'),
[r'سؤال.',r'جدول الوضع النسبي ثم الرسم.',r'تلوين الحيز.',r'تقويم فردي.']))
# ---------------------------------------------------------------- 42
S.append(sess('42',r'القيمة المتوسطة لدالة على مجال ، حصر تكامل',
[r'خواص التكامل.'],
[r'حساب القيمة المتوسطة لدالة وتفسيرها.',r'حصر تكامل.'],TOOLS,
r'درجات الحرارة خلال يوم تتغير باستمرار: ما معنى «الحرارة المتوسطة»؟',
ACT('07')+r'\ $f(x)=x^2$ على $[0;3]$.'+Q(r'احسب $'+I('0','3','x^2')+r'$.',r'عيّن ارتفاع مستطيل قاعدته $[0;3]$ وله نفس المساحة.')
+DIS()+Q(r'$\left[\dfrac{x^3}3\right]_0^3=\RR{9}$.',r'$3\times h=9$ ، إذن $h=\RR{3}$: هي \textbf{القيمة المتوسطة} لـ $f$ على $[0;3]$.'),
DEF()+r'\ القيمة المتوسطة لـ $f$ على $[a;b]$ ($a<b$): $\RR{\mu=\dfrac1{b-a}'+I('a','b','f(x)')+r'}$.'
+PRO('الحصر')+r'\ إذا كان $m\leqslant f(x)\leqslant M$ على $[a;b]$ فإن: $\RR{m(b-a)\leqslant'+I('a','b','f(x)')+r'\leqslant M(b-a)}$.'
+EX('أمثلة محلولة')+Q(r'القيمة المتوسطة لـ $e^x$ على $[0;1]$: $\mu=\dfrac11\big[e^x\big]_0^1=\RR{e-1}$.',r'من أجل $x\in[0;1]$: $0\leqslant x^2\leqslant1$ ، إذن $1\leqslant e^{x^2}\leqslant e$ ، ومنه $\RR{1\leqslant'+I('0','1','e^{x^2}')+r'\leqslant e}$.')
+WARN()+r'\ لا نستطيع حساب $\int e^{x^2}$ بدالة أصلية مألوفة: الحصر هو الحل.',
TT()+r'\par'+Q(r'احسب القيمة المتوسطة لـ $\sin$ على $[0;\pi]$.',r'بيّن أن $\dfrac12\leqslant'+I('0','1',r'\dfrac1{1+x^2}')+r'\leqslant1$.')
+SOL()+Q(r'$\mu=\dfrac1\pi\big[-\cos x\big]_0^\pi=\dfrac1\pi(1+1)=\RR{\dfrac2\pi}$.',r'على $[0;1]$: $1\leqslant1+x^2\leqslant2$ ، إذن $\dfrac12\leqslant\dfrac1{1+x^2}\leqslant1$ ، وبالحصر (الطول $1$) نحصل على \RR{المطلوب}.')
+HW(r'تمرين 36 صفحة 186 ، وتمرين 51 صفحة 188.'),
[r'وضعية مناخية.',r'تفسير هندسي.',r'الحصر.',r'تقويم فردي.']))
# ---------------------------------------------------------------- 43
G43=GR(r'''\fill[cEx!30] (-2,0) -- plot[domain=-2:2,samples=50] (\x,{\x*\x-4}) -- (2,0) -- cycle;
\draw[cDef,very thick,domain=-2.6:2.6,samples=60] plot (\x,{\x*\x-4}) node[right]{$(C_f)$};
\node[cThm] at (0.6,-1.8){$\mathcal A$};''',(-3,3.2),(-4.6,3),x=0.8,y=0.45)
G43b=GR(r'''\fill[cDef!30] (0,0) -- plot[domain=0:1,samples=40] (\x,{\x*\x-1}) -- cycle;
\fill[cEx!35] (1,0) -- plot[domain=1:2,samples=40] (\x,{\x*\x-1}) -- (2,0) -- cycle;
\draw[cDef,very thick,domain=-0.5:2.2,samples=60] plot (\x,{\x*\x-1}) node[right]{$(C_f)$};
\draw[densely dotted] (2,0)--(2,3); \node at (0.45,-0.4){$\mathcal A_1$}; \node at (1.75,0.8){$\mathcal A_2$};''',(-0.8,2.7),(-1.6,3.6),x=1.4,y=0.7)
S.append(sess('43',r'حساب مساحة حيز: حالة دالة سالبة أو متغيرة الإشارة',
[r'التكامل ، الوضع النسبي.'],
[r'حساب مساحة حيز يقع تحت محور الفواصل أو على جانبيه.'],TOOLS,
r'ما إشارة $'+I('-2','2','(x^2-4)')+r'$ ؟ هل المساحة سالبة؟',
ACT('08')+r'\ $f(x)=x^2-4$ على $[-2;2]$.'+Q(r'ادرس إشارة $f(x)$ على $[-2;2]$.',r'احسب $'+I('-2','2','f(x)')+r'$ ، وقارنه بالمساحة.')
+DIS()+Q(r'$f(x)=(x-2)(x+2)\leqslant0$ على $[-2;2]$: $(C_f)$ \RR{تحت} محور الفواصل.',r'$\left[\dfrac{x^3}3-4x\right]_{-2}^2=\left(\dfrac83-8\right)-\left(-\dfrac83+8\right)=\RR{-\dfrac{32}3}$: التكامل سالب ، والمساحة \RR{$\dfrac{32}3$}.'),
PRO()+Q(r'إذا كانت $f\leqslant0$ على $[a;b]$: $\RR{\mathcal A=-'+I('a','b','f(x)')+r'}$.',r'إذا تغيرت الإشارة: نقسم المجال عند الأصفار (علاقة شال) ونجمع المساحات.')
+EX('مثال 1: الوضع النسبي ثم الرسم')+VP(['-2','2'],'x^2-4',{0:'A(-2;0)',1:'B(2;0)'},['تحت'],'(C_f)',"(xx')")+G43
+r'$\mathcal A=-'+I('-2','2','(x^2-4)')+r'=\RR{\dfrac{32}3\ \mathrm{u.a}}$.'
+EX('مثال 2: دالة متغيرة الإشارة')+r'\ $f(x)=x^2-1$ على $[0;2]$:'+VP(['0','1','2'],'x^2-1',{1:'A(1;0)'},['تحت','فوق'],'(C_f)',"(xx')")+G43b
+Q(r'$\mathcal A_1=-'+I('0','1','(x^2-1)')+r'=-\left(\dfrac13-1\right)=\RR{\dfrac23}$.',r'$\mathcal A_2='+I('1','2','(x^2-1)')+r'=\left(\dfrac83-2\right)-\left(\dfrac13-1\right)=\RR{\dfrac43}$ ؛ $\mathcal A=\RR{2\ \mathrm{u.a}}$.')
+WARN()+r'\ المساحة دائمًا موجبة.',
TT()+r'\par احسب مساحة الحيز بين منحنى $\sin$ ومحور الفواصل على $[0;2\pi]$.'
+SOL()+VP(['0',r'\pi',r'2\pi'],r'\sin x',{0:'O(0;0)',1:r'A(\pi;0)',2:r'B(2\pi;0)'},['فوق','تحت'],'(C)',"(xx')")
+Q(r'$\mathcal A_1='+I('0',r'\pi',r'\sin x')+r'=\big[-\cos x\big]_0^\pi=\RR{2}$.',r'$\mathcal A_2=-'+I(r'\pi',r'2\pi',r'\sin x')+r'=-\big[-\cos x\big]_\pi^{2\pi}=\RR{2}$ ؛ $\mathcal A=\RR{4\ \mathrm{u.a}}$.')
+HW(r'تمارين 52 إلى 59 صفحتي 188 و 189.'),
[r'سؤال إشكالي.',r'جدول الوضع النسبي.',r'تلوين الحيز بلونين.',r'تقويم فردي.']))
# ---------------------------------------------------------------- 44
S.append(sess('44',r'التكامل بالتجزئة ، توظيف التكامل لحساب دوال أصلية',
[r'خواص التكامل ، مشتقة جداء.'],
[r'حساب تكاملات بالتجزئة.',r'تعيين دوال أصلية بالتكامل.'],TOOLS,
r'كيف نحسب $'+I('0','1','xe^x')+r'$ ؟ لا يوجد في الجدول.',
ACT('09')+Q(r'اكتب مشتقة الجداء $uv$.',r'كامل طرفي المساواة على $[a;b]$ واستنتج دستورًا.')
+DIS()+Q(r'$(uv)^{\prime}=u^{\prime}v+uv^{\prime}$.',r'$\big[uv\big]_a^b=\int_a^bu^{\prime}v+\int_a^buv^{\prime}$ ، ومنه $\RR{\int_a^buv^{\prime}=\big[uv\big]_a^b-\int_a^bu^{\prime}v}$.'),
PRO('التكامل بالتجزئة')+r'\ $u$ و $v$ قابلتان للاشتقاق ومشتقتاهما مستمرتان: $\RR{'+I('a','b',r'u(x)v^{\prime}(x)')+r'=\big[u(x)v(x)\big]_a^b-'+I('a','b',r'u^{\prime}(x)v(x)')+r'}$.'
+EX('أمثلة محلولة')+Q(r'$'+I('0','1','xe^x')+r'$: $u=x$ ، $v^{\prime}=e^x$ ، $u^{\prime}=1$ ، $v=e^x$:\par $=\big[xe^x\big]_0^1-'+I('0','1','e^x')+r'=e-(e-1)=\RR{1}$.',r'$'+I('1','e',r'\ln x')+r'$: $u=\ln x$ ، $v^{\prime}=1$ ، $v=x$:\par $=\big[x\ln x\big]_1^e-'+I('1','e','1')+r'=e-(e-1)=\RR{1}$.')
+PRO('دالة أصلية بالتكامل')+r'\ $x\mapsto\displaystyle\int_a^xf(t)\,\mathrm dt$ هي \RR{الدالة الأصلية لـ $f$ التي تنعدم عند $a$}. مثال: $\displaystyle\int_1^x\ln t\,\mathrm dt=\RR{x\ln x-x+1}$.'
+WARN()+r'\ نختار $u$ التي تبسط بالاشتقاق ($x$ ، $\ln x$).',
TT()+r'\par احسب:'+Q(r'$'+I('0',r'\pi',r'x\cos x')+r'$.',r'$'+I('1','e',r'x\ln x')+r'$.')
+SOL()+Q(r'$u=x$ ، $v^{\prime}=\cos x$ ، $v=\sin x$: $\big[x\sin x\big]_0^\pi-'+I('0',r'\pi',r'\sin x')+r'=0-2=\RR{-2}$.',r'$u=\ln x$ ، $v^{\prime}=x$ ، $v=\dfrac{x^2}2$: $\left[\dfrac{x^2}2\ln x\right]_1^e-'+I('1','e',r'\dfrac x2')+r'=\dfrac{e^2}2-\dfrac{e^2-1}4=\RR{\dfrac{e^2+1}4}$.')
+HW(r'تمارين 62 إلى 65 ، و 68 إلى 70 صفحة 189.'),
[r'سؤال.',r'مشتقة الجداء.',r'اختيار $u$ و $v^{\prime}$.',r'تقويم فردي.']))
