S.append(sess('45',r'حساب حجوم مجسمات بسيطة ، حل مشكلات',
[r'الحساب التكاملي.'],
[r'حساب حجم مجسم بالتكامل.',r'توظيف التكامل في حل مشكلات بسيطة.'],TOOLS,
r'كيف نبرهن أن حجم المخروط ثلث حجم الأسطوانة؟',
ACT('10')+r'\ مخروط دوراني نصف قطر قاعدته $r$ وارتفاعه $h$ ، رأسه في $O$ ومحوره محور الفواصل.'+Q(r'عبّر عن نصف قطر المقطع عند الفاصلة $x$ ($0\leqslant x\leqslant h$).',r'استنتج مساحة المقطع $S(x)$.')
+DIS()+Q(r'بتناسب المثلثين: نصف القطر $\RR{\dfrac{rx}h}$.',r'$S(x)=\pi\left(\dfrac{rx}h\right)^2=\RR{\dfrac{\pi r^2x^2}{h^2}}$.'),
PRO()+Q(r'حجم مجسم مساحة مقطعه $S(x)$ على $[a;b]$: $\RR{V='+I('a','b','S(x)')+r'}$.',r'مجسم دوراني حول محور الفواصل: $\RR{V=\pi'+I('a','b','f(x)^2')+r'}$.')
+EX('أمثلة محلولة')+Q(r'المخروط: $V='+I('0','h',r'\dfrac{\pi r^2x^2}{h^2}')+r'=\dfrac{\pi r^2}{h^2}\times\dfrac{h^3}3=\RR{\dfrac{\pi r^2h}3}$.',r'الكرة: دوران $f(x)=\sqrt{r^2-x^2}$ على $[-r;r]$: $V=\pi'+I('-r','r','(r^2-x^2)')+r'=\RR{\dfrac43\pi r^3}$.')
+WARN()+r'\ وحدة الحجم $\mathrm{u.v}$.',
TT()+r'\par احسب حجم المجسم الناتج عن دوران المنحنى حول محور الفواصل:'+Q(r'$f(x)=\sqrt x$ على $[0;4]$.',r'$g(x)=e^x$ على $[0;1]$.')
+SOL()+Q(r'$V=\pi'+I('0','4','x')+r'=\pi\left[\dfrac{x^2}2\right]_0^4=\RR{8\pi\ \mathrm{u.v}}$.',r'$V=\pi'+I('0','1','e^{2x}')+r'=\RR{\dfrac{\pi\left(e^2-1\right)}2\ \mathrm{u.v}}$.')
+HW(r'تمرينا 72 و 73 صفحة 189.'),
[r'سؤال تاريخي.',r'نموذج حقيقي.',r'رسم المقطع.',r'نهاية المحور: فرض أو مراجعة.']))
